public class Truck {
    private final Supplier<GpsUnit> gps;

    @Inject
    public Truck(Driver driver, Supplier<GpsUnit> gps) { this.gps = gps; }

    public String directions() {
        return gps.get().directionsTo("the new house");   // builds once only if the Supplier remembers
    }
}

// a Supplier that remembers, written by hand
static <T> Supplier<T> memoize(Supplier<T> make) {
    return new Supplier<>() {
        private volatile T value;
        public synchronized T get() { if (value == null) value = make.get(); return value; }
    };
}

