class Once<T : Any>(private val make: () -> T) {
    @Volatile private var made: T? = null

    val value: T
        get() {
            made?.let { return it }                 // fast path: already built
            synchronized(this) {
                made?.let { return it }             // look again with the lock held
                return make().also { made = it }    // build once
            }
        }
}

val gps = Once { GpsUnit() }                        // nothing built yet
println(gps.value === gps.value)                   // true: built on the first .value

