final class Once<T> implements Supplier<T> {
    private final Supplier<T> make;
    private volatile T made;

    Once(Supplier<T> make) { this.make = make; }

    @Override
    public T get() {
        T result = made;
        if (result != null) return result;          // fast path: already built
        synchronized (this) {
            if (made == null) made = make.get();    // look again with the lock held, build once
            return made;
        }
    }
}
